"use strict";(self.webpackChunksedelpeuch_net=self.webpackChunksedelpeuch_net||[]).push([[17387],{98078(e){e.exports=JSON.parse('{"tag":{"label":"docker","permalink":"/docs/tags/docker","allTagsPath":"/docs/tags","count":9,"items":[{"id":"projects/professionnel/bluenav-jumeau-numerique","title":"BlueNav - Jumeau num\xe9rique bateau autonome","description":"Jumeau num\xe9rique du BlueBoat, navire autonome de 12 tonnes destin\xe9 aux voies fluviales : mod\xe8le physique, environnement fluvial et capteurs simul\xe9s sous ROS 2 et Gazebo, pour valider les algorithmes de navigation de BlueNav avant la mise \xe0 l\'eau.","permalink":"/docs/projects/professionnel/bluenav-jumeau-numerique"},{"id":"projects/personnel/body_analysis","title":"Body Analysis","description":"Application de suivi et d\'analyse corporelle (FastAPI, React, PostgreSQL, MinIO) : ingestion des exports Samsung Health, analytics d\'entra\xeenement (TRIMP, ACWR, d\xe9rive cardiaque), r\xe9cup\xe9ration et sommeil, galerie photo confidentielle.","permalink":"/docs/projects/personnel/body_analysis"},{"id":"projects/professionnel/cicd","title":"CI/CD - Workflows GitHub Actions mutualis\xe9s","description":"Biblioth\xe8que de workflows GitHub Actions r\xe9utilisables (g\xe9n\xe9rique, Python, ROS, Mbed, Zephyr) appel\xe9e par plusieurs dizaines de d\xe9p\xf4ts de l\'organisation CATIE, du test au d\xe9ploiement Helm ou Compose, document\xe9e et v\xe9rifi\xe9e contre son code.","permalink":"/docs/projects/professionnel/cicd"},{"id":"projects/personnel/colis-tracker","title":"Colis Tracker","description":"Suivi de colis Colissimo et Chronopost auto-h\xe9berg\xe9, sans cl\xe9 API ni service tiers : interrogation de l\'endpoint de suivi public de La Poste, import automatique des num\xe9ros depuis les mails d\'exp\xe9dition (IMAP), notifications ntfy.","permalink":"/docs/projects/personnel/colis-tracker"},{"id":"projects/personnel/dolibarr_project_dashboard","title":"Dolibarr Project Dashboard","description":"Tableau de bord FastAPI + React qui agr\xe8ge les donn\xe9es de plusieurs projets Dolibarr (t\xe2ches, temps pass\xe9, factures, opportunit\xe9s) pour le pilotage multi-projets, livr\xe9 en image Docker unique.","permalink":"/docs/projects/personnel/dolibarr_project_dashboard"},{"id":"projects/professionnel/github-arc-kubeadm","title":"GitHub ARC - Runners CI/CD auto-h\xe9berg\xe9s sur Kubernetes","description":"D\xe9ploiement de GitHub Actions Runner Controller (ARC) sur le cluster Kubernetes kubeadm du CATIE. Runners \xe9ph\xe9m\xe8res Docker-in-Docker de 10 \xe0 60 pods, m\xe9triques Prometheus, caches CI partag\xe9s et correction des probl\xe8mes de MTU.","permalink":"/docs/projects/professionnel/github-arc-kubeadm"},{"id":"projects/personnel/homelab","title":"HomeLab","description":"Homelab auto-h\xe9berg\xe9 versionn\xe9 en GitOps (Docker Compose, reverse proxy et SSO, CI/CD GitHub Actions, mises \xe0 jour Renovate, secrets chiffr\xe9s en repo, sauvegardes 3-2-1 chiffr\xe9es, supervision et alerting, hub mail, DNS local, documentation g\xe9n\xe9r\xe9e depuis le code).","permalink":"/docs/projects/personnel/homelab"},{"id":"projects/personnel/meeting-recorder","title":"Meeting Recorder","description":"Enregistreur de r\xe9unions enti\xe8rement local : capture deux pistes (micro et sortie son), transcription faster-whisper, synth\xe8se par un LLM local via Ollama, notes de r\xe9union fusionn\xe9es au compte rendu. Microservices Docker Compose, profils GPU 4 Go et CPU.","permalink":"/docs/projects/personnel/meeting-recorder"},{"id":"projects/personnel/recallarr","title":"Recallarr","description":"Journal personnel de ce qui a \xe9t\xe9 regard\xe9 dans Jellyfin, qui survit au nettoyage de la m\xe9diath\xe8que : synchronisation par webhook et r\xe9conciliation quotidienne, r\xe8gles de note et de favori, devenir de chaque titre, interface HTMX.","permalink":"/docs/projects/personnel/recallarr"}],"unlisted":false}}')}}]);